import{_ as r,C as n,o,c as i,a3 as a,b as d,w as t,a as h,E as c,ac as l}from"./chunks/framework.DEI_cgrW.js";const w=JSON.parse('{"title":"Deploying the server","description":"","frontmatter":{},"headers":[],"relativePath":"docs/deploying-the-server.md","filePath":"docs/deploying-the-server.md"}'),p={name:"docs/deploying-the-server.md"};function g(u,e,y,k,m,f){const s=n("Mermaid");return o(),i("div",null,[e[1]||(e[1]=a('<h1 id="deploying-the-server" tabindex="-1">Deploying the server <a class="header-anchor" href="#deploying-the-server" aria-label="Permalink to &quot;Deploying the server&quot;">​</a></h1><p>The server runs on one Linux machine as Docker containers, behind a shared Caddy for HTTPS. Health data must stay in the EU or Switzerland under the GDPR, so pick a host there (<a href="./architecture#accounts-and-security">architecture</a>). The server answers <code>/health</code> with its version and serves <a href="./the-api">the API</a> under <code>/api/v1</code>. It connects to Postgres and applies its migrations on start (<a href="./adr/0022-the-servers-schema-is-sqldelight-migrations-on-postgres">ADR 0022</a>); <code>/health</code> answers 503 while Postgres doesn&#39;t. Postgres holds only the schema&#39;s version until accounts arrive (<a href="https://github.com/tkint/coach-poulpy/issues/25" target="_blank" rel="noreferrer">#25</a>).</p><p>The setup follows <a href="./adr/0019-the-server-runs-with-docker-compose-on-one-server">ADR 0019</a>. Deployment files are in <a href="https://github.com/tkint/coach-poulpy/tree/main/deploy" target="_blank" rel="noreferrer"><code>deploy/</code></a>, and each <a href="./releasing#the-server">release</a> includes a deployment bundle.</p><h2 id="the-containers" tabindex="-1">The containers <a class="header-anchor" href="#the-containers" aria-label="Permalink to &quot;The containers&quot;">​</a></h2>',4)),(o(),d(l,null,{default:t(()=>[c(s,{id:"mermaid-12",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20internet((%22Internet%22))%20--%20%2280%20and%20443%22%20--%3E%20caddy%0A%20%20%20%20subgraph%20edgeproj%5B%22edge%20project%22%5D%0A%20%20%20%20%20%20%20%20caddy%5B%22caddy%20%C2%B7%20shared%20HTTPS%22%5D%0A%20%20%20%20end%0A%20%20%20%20subgraph%20appproj%5B%22coach-poulpy%20project%22%5D%0A%20%20%20%20%20%20%20%20server%5B%22server%20%C2%B7%20coach-poulpy-server%3A8080%22%5D%0A%20%20%20%20%20%20%20%20postgres%5B(%22postgres%20%C2%B7%20postgres-data%22)%5D%0A%20%20%20%20end%0A%20%20%20%20caddy%20--%20%22edge%20network%22%20--%3E%20server%0A%20%20%20%20server%20--%20%22internal%20network%22%20--%3E%20postgres%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[h(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a(`<p>Only Caddy publishes ports. The server reaches Postgres at <code>postgres:5432</code> with the <code>POSTGRES_PASSWORD</code> from <code>.env</code>, and starts once Postgres is healthy. The server joins the external <code>edge</code> network using a unique alias and the private <code>internal</code> network; Postgres joins only <code>internal</code>. The app and edge are separate Compose projects, so stopping the app leaves Caddy running. The shared network is for trusted applications: containers on it can reach each other&#39;s app ports.</p><p>The server runs on Jetty, which holds the phones&#39; server-sent event streams open (Caddy passes them through as they come). It runs as <strong>one container</strong>: who is listening for a confirmed email lives in its memory, so a second replica would need those events shared first.</p><h2 id="what-you-need" tabindex="-1">What you need <a class="header-anchor" href="#what-you-need" aria-label="Permalink to &quot;What you need&quot;">​</a></h2><ul><li>Linux with Python 3, Docker Engine and Docker Compose.</li><li>About 1 GB of free memory; the server is capped at 512 MB. Images are built in CI, not on the machine.</li><li>An API hostname (<code>api.coach-poulpy.com</code>) and a web app hostname (<code>app.coach-poulpy.com</code>) whose DNS A/AAAA records point to the machine. The landing site gets its own hostname and container later (<a href="./adr/0021-the-landing-site-the-app-and-the-api-have-their-own-hostname">ADR 0021</a>).</li><li>SSH and ports 80/443 open (TCP, plus UDP 443 for HTTP/3).</li></ul><p>If <code>ghcr.io/tkint/coach-poulpy-server</code> or <code>ghcr.io/tkint/coach-poulpy-web</code> is private (a package&#39;s first push makes it private), log the machine in once with a token that can read packages: <code>docker login ghcr.io</code>.</p><h2 id="deploy" tabindex="-1">Deploy <a class="header-anchor" href="#deploy" aria-label="Permalink to &quot;Deploy&quot;">​</a></h2><p>Everything is deployed from GitHub; you don&#39;t log in to the machine for it. Set up the <strong>Deploy</strong> workflow once (<a href="./releasing#deploy-the-server">Releasing</a>), with <code>DOMAIN</code> and <code>POSTGRES_PASSWORD</code> in the <code>production</code> environment, then run <strong>Actions &gt; Deploy &gt; Run workflow</strong> with <code>latest</code> or a version. Check it with <code>curl https://api.coach-poulpy.com/health</code>.</p><p>The workflow writes <code>~/coach-poulpy/.env</code> from those settings (replaced on every run, so change settings in GitHub, not on the machine), uploads <code>compose.yaml</code> and the site file to <code>~/coach-poulpy</code>, and the shared Caddy to <code>~/caddy</code>. On the machine, <code>~/caddy/deploy.py</code> then:</p><ul><li>creates the external <code>edge</code> network and starts Caddy if needed,</li><li>pulls and starts the server and Postgres,</li><li>adds the site to Caddy through its admin API, or replaces it if already there.</li></ul><p>Caddy keeps the configuration it receives through the API in its <code>caddy-config</code> volume and resumes it after a restart; <code>bootstrap.json</code> is only used before the first site is added. Other sites on the same Caddy are left alone, and deployments wait for each other. To change the hostname, update <code>DOMAIN</code> in GitHub and deploy again. Any branch can be deployed by hand to a <code>preview</code> environment, beside production or in its place (<a href="./releasing#deploy-a-pull-request">Deploy a pull request</a>). HTTPS errors are usually caused by DNS or blocked ports; inspect <code>cd ~/caddy &amp;&amp; docker compose logs caddy</code>.</p><p>Mail goes out over SMTP to the provider in <code>SMTP_HOST</code>, <code>SMTP_PORT</code>, <code>SMTP_USER</code>, <code>SMTP_PASSWORD</code> and <code>MAIL_FROM</code>, which the Deploy workflow writes to <code>.env</code> from the environment (<a href="./releasing#deploy-the-server">Releasing</a>); changing provider is a new deploy, not a code change. <code>MAIL_FROM</code> is only the default sender: an admin can save another from-address in the admin, which wins from the next email on (<a href="./admin#settings">the admin area</a>). Port 465 uses implicit TLS, any other requires STARTTLS. Until <code>SMTP_HOST</code> is set, the server sends no email at all: each one fails with a clear error (<code>No mail server is set: SMTP_HOST is unset</code>), nothing of it is printed, and the admin&#39;s <a href="./admin#status">Status</a> says mail isn&#39;t configured. Sign-ups still work but their confirmation link never leaves, so set <code>SMTP_HOST</code> before opening sign-up. The links point at <code>WEBSITE_URL</code>, the website by default.</p><p><code>POSTGRES_PASSWORD</code> only takes effect when the Postgres volume is first created; changing it later needs a password change inside Postgres too.</p><p>If another Caddy already holds ports 80/443, remove that container once before the first deploy (<code>docker rm -f &lt;container&gt;</code>); the shared Caddy requests the certificates again. Never use <code>docker compose down -v</code>: it deletes the volumes.</p><h2 id="the-web-app" tabindex="-1">The web app <a class="header-anchor" href="#the-web-app" aria-label="Permalink to &quot;The web app&quot;">​</a></h2><p><code>app.coach-poulpy.com</code> is a separate container and Caddy route (<a href="./adr/0021-the-landing-site-the-app-and-the-api-have-their-own-hostname">ADR 0021</a>): the Vue app from <code>web/</code>, served as static files, with every page path answered by the app. Deploy it with <strong>Actions &gt; Deploy &gt; Run workflow</strong>, <strong>What to deploy</strong> <code>website</code>, after setting <code>WEB_DOMAIN</code> in the environment (<a href="./releasing#deploy-the-server">Releasing</a>). It lands in <code>~/coach-poulpy-web</code> (the server&#39;s <code>APP_NAME</code> followed by <code>-web</code>), from <a href="https://github.com/tkint/coach-poulpy/tree/main/deploy/web" target="_blank" rel="noreferrer"><code>deploy/web/</code></a>, and never restarts the server. Check it with <code>curl https://app.coach-poulpy.com/.well-known/assetlinks.json</code>.</p><p>The account emails link to <code>/confirm-email#&lt;token&gt;</code> and <code>/reset-password#&lt;token&gt;</code> there; when a link opens in a browser, those pages confirm the email or set the new password through the API, which accepts browser calls from the origin of <code>WEBSITE_URL</code> only. The image carries <code>/.well-known/assetlinks.json</code>, built from the Android signing key, so Android opens those links in the app; a build without the key (a deploy with no <code>ANDROID_KEYSTORE_*</code> secrets) leaves it out and the links open in the browser. The iPhone&#39;s <code>apple-app-site-association</code> waits on an Apple Developer account (<a href="https://github.com/tkint/coach-poulpy/issues/24" target="_blank" rel="noreferrer">#24</a>).</p><h2 id="logs" tabindex="-1">Logs <a class="header-anchor" href="#logs" aria-label="Permalink to &quot;Logs&quot;">​</a></h2><p>Containers log to Docker&#39;s <code>json-file</code> driver, capped at 3 files of 10 MB each, so on the machine <code>docker compose logs server</code> only reaches back a short while. To read them from anywhere, with longer retention and search, the deploy can ship them to the free tier of <a href="https://grafana.com/products/cloud/" target="_blank" rel="noreferrer">Grafana Cloud</a> (Loki). Pick an EU region when creating the stack, for the same GDPR reason as the host.</p><ol><li>Create a free Grafana Cloud stack in an EU region.</li><li>In the stack&#39;s <strong>Loki</strong> details, copy the push URL (<code>https://logs-prod-XXX.grafana.net/loki/api/v1/push</code>) and the user ID.</li><li>Under <strong>Administration &gt; Access policies</strong>, create a policy with the <code>logs:write</code> scope only and generate a token from it.</li><li>Add <code>LOKI_URL</code>, <code>LOKI_USER</code> (variables) and <code>LOKI_PASSWORD</code> (secret, the token) to the <code>production</code> environment (<a href="./releasing#deploy-the-server">Releasing</a>), then deploy again.</li></ol><p>With all three set, the Deploy workflow writes <code>COMPOSE_PROFILES=logs</code> to <code>.env</code> and an <code>alloy</code> container (Grafana Alloy, <a href="https://github.com/tkint/coach-poulpy/tree/main/deploy/alloy" target="_blank" rel="noreferrer"><code>deploy/alloy/config.alloy</code></a>) starts beside the server. It reads the logs of this Compose project&#39;s containers through the read-only Docker socket and pushes them to Loki, labelled <code>app</code>, <code>environment</code> and <code>service</code> (<code>server</code> or <code>postgres</code>). In Grafana, <strong>Explore</strong> with the Loki data source and <code>{app=&quot;coach-poulpy&quot;, service=&quot;server&quot;}</code> shows the server. Setting only some of the three stops the deploy; setting none leaves the logs on the machine. Alloy needs about 256 MB more memory. If you remove the settings after enabling them, stop Alloy once with <code>docker compose --profile logs stop alloy</code>.</p><p>Logs leave the machine, so they must not hold personal data. The server prints no secrets and never an email: without <code>SMTP_HOST</code> it sends none rather than printing them (<a href="https://github.com/tkint/coach-poulpy/issues/340" target="_blank" rel="noreferrer">#340</a>), and a sent one is logged with a masked address (<code>a…@example.com</code>). Check the free tier&#39;s limits (monthly volume and retention) on Grafana&#39;s pricing page, as they change.</p><h2 id="backups" tabindex="-1">Backups <a class="header-anchor" href="#backups" aria-label="Permalink to &quot;Backups&quot;">​</a></h2><p>Postgres has nothing to back up until accounts arrive. After that, dump it nightly and before deploying a release with new migrations, since an older server refuses a migrated database, and store the dumps off-machine in the EU or Switzerland:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkdir</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/backups</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/coach-poulpy</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -T</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> postgres</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pg_dump</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -U</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> coachpoulpy</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -Fc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> coachpoulpy</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/backups/coachpoulpy-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">date</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +%F</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.dump</span></span></code></pre></div><p>Restore with <code>pg_restore -U coachpoulpy -d coachpoulpy --clean</code>, fed through <code>docker compose exec -T postgres</code>. Back up <code>.env</code> and the shared edge&#39;s configuration and migration state as well. Losing Caddy&#39;s certificate volume requires issuing new certificates.</p>`,25))])}const b=r(p,[["render",g]]);export{w as __pageData,b as default};
